insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('fraise', 'fraise', array[]::text[], 'list', $r$[{"title":"Charlotte aux fraises","intro":"Des biscuits à la cuillère autour d'une mousse légère aux fraises.","minutes":40,"calories":350,"difficulty":"Moyen","imageSearch":"strawberry charlotte","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits à la cuillère","plural":"biscuits à la cuillère","qty":24,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"gélatine","plural":"feuilles de gélatine","qty":4,"unit":"feuilles","have":false}],"steps":[{"text":"Fais ramollir la gélatine dans l'eau froide. Mixe la moitié des fraises avec le sucre.","timer":null},{"text":"Chauffe un peu de ce coulis et fais-y fondre la gélatine, puis mélange au reste.","timer":null},{"text":"Fouette la crème en chantilly et mélange-la au fromage blanc et au coulis.","timer":null},{"text":"Trempe rapidement les biscuits dans de l'eau sucrée et tapisse un moule.","timer":null},{"text":"Alterne mousse et fraises coupées, puis couvre de biscuits.","timer":null},{"text":"Laisse prendre 6 h au frais avant de démouler.","timer":null}],"dessert":true},{"title":"Salade de fruits rouges à la menthe","intro":"Une salade d'été aux fraises, framboises et menthe.","minutes":15,"calories":120,"difficulty":"Facile","imageSearch":"berry salad mint","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"framboise","plural":"framboises","qty":125,"unit":"g","have":false},{"name":"myrtille","plural":"myrtilles","qty":125,"unit":"g