uf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":80,"unit":"g","have":false},{"name":"poire","plural":"poires","qty":2,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais fondre le chocolat.","timer":null},{"text":"Mélange la poudre d'amande, le sucre, le beurre, 2 œufs et le chocolat fondu.","timer":null},{"text":"Étale une pâte, garnis de frangipane et de poires en dés, et pose la fève.","timer":null},{"text":"Couvre de la seconde pâte, soude les bords et dore au dernier œuf.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"dessert":true},{"title":"Crumble healthy à l'avoine","intro":"Un crumble croustillant et plus léger, aux flocons d'avoine.","minutes":45,"calories":260,"difficulty":"Facile","imageSearch":"oat crumble healthy","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"poire","plural":"poires","qty":2,"unit":"","have":false},{"name":"flocons d'avoine","plural":"flocons d'avoine","qty":80,"unit":"g","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":40,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"miel","plural":"miel","qty":2,"unit":"c. à s.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mets les fruits en morceaux dans un plat avec la cannelle.","timer":null},{"text":"Mélange les flocons, la poudre d'amande, le beurre fondu et le miel, et répartis sur les fruits.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"dessert":true},{"title":"Tatin de poires","intro":"La tatin revisitée, aux poires caramélisées.","minutes":60,"calories":370,"difficulty":"Moyen","imageSearch":"pear tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":1,"unit":"","have":false},{"name":"poire","plural":"poires","qty":6,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Fais un caramel avec le sucre, ajoute le beurre.","timer":{"label":"Caramel","min":6}},{"text":"Range les poires en quartiers dans le caramel, couvre de pâte.","timer":null},{"text":"Enfourne 30 min, puis retourne.","timer":{"label":"Four","min":30}}],"dessert":true},{"title":"Compote pommes-poires","intro":"Une compote douce, sucrée seulement par les fruits.","minutes":30,"calories":100,"difficulty":"Facile","imageSearch":"apple pear compote","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Épluche les fruits, retire le cœur et coupe-les en morceaux.","timer":null},{"text":"Mets-les dans une casserole avec 5 cl d'eau et la cannelle.","timer":null},{"text":"Fais cuire 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Écrase ou mixe, puis laisse refroidir.","timer":null}],"kids":true,"dessert":true},{"title":"Poires pochées au vin rouge","intro":"Des poires rouges et parfumées, pour un dessert d'hiver.","minutes":50,"calories":250,"difficulty":"Facile","imageSearch":"poached pears red wine","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"poire","plural":"poires","qty":4,"unit":"","have":false},{"name":"vin rouge","plural":"vin rouge","qty":75,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"bâton de cannelle","plural":"bâtons de cannelle","qty":1,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false}],"steps":[{"text":"Porte à ébullition le vin avec le sucre, la cannelle et le zeste de l'orange.","timer":null},{"text":"Épluche les poires en gardant la queue.","timer":null},{"text":"Poche-les 30 min dans le vin frémissant en les retournant.","timer":{"label":"Cuisson","min":30}},{"text":"Retire les poires et fais réduire le vin en sirop.","timer":{"label":"Cuisson","min":10}},{"text":"Sers tiède ou froid, nappé de sirop.","timer":null}],"dessert":true}]$r$::jsonb, 'claude')
